#!/usr/bin/env python3
"""Write web/school-data.js from the «school» section of a data file, so the page and the data file never drift.

Usage: python3 make_school_data.py school-budgets-data.json path/to/web/school-data.js
"""
import json
import sys

HEAD = """// School data for the budgets section: everything that belongs to one school, nothing that is code.
// Generated by the «school-budgets» skill (scripts/make_school_data.py) from the data file's «school» section.
// Class ids: '10-1' (grade 10), '11a-1' / '12a-1' (literary «د»), '11s-1' / '12s-1' (scientific «ع»).
"""


def main(src, out):
    school = json.load(open(src, encoding="utf-8"))["school"]
    body = json.dumps(school, ensure_ascii=False, indent=2)
    open(out, "w", encoding="utf-8").write(HEAD + "const SCHOOL_DATA = " + body + ";\n")
    print("كُتب", out)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
